// ======================================================
// START / STOP AFHANDELING
// ======================================================

// Verwacht invoer:
// - msg.payload === true  → START ON
// - msg.payload === false → START OFF

const run = msg.payload;

// ======================================================
// TIMER MANAGEMENT
// ======================================================

// Alle actieve timers bewaren
let timers = context.get('timers') || [];

function addTimer(t) {
    timers.push(t);
    context.set('timers', timers);
}

// Alles stoppen/resetten
function clearAllTimers() {
    timers = context.get('timers') || [];

    timers.forEach(t => clearTimeout(t));

    timers = [];
    context.set('timers', timers);
}

// ======================================================
// STATUS LOGGING
// ======================================================

function status(txt) {
    node.send([null, null, null, { payload: txt }]);
}

// ======================================================
// HOORN CONTROL (OVERLAP VEILIG)
// ======================================================

function hornOn(label = '') {

    let count = context.get('hornCount') || 0;
    count++;

    context.set('hornCount', count);

    status(`HOORN AAN ${label}`);

    node.send([
        null,
        { payload: { outputs: { hoorn: 1 } } },
        null,
        null
    ]);
}

function hornOff(label = '') {

    let count = context.get('hornCount') || 0;

    count--;

    if (count <= 0) {

        count = 0;

        status(`HOORN UIT ${label}`);

        node.send([
            null,
            { payload: { outputs: { hoorn: 0 } } },
            null,
            null
        ]);
    }

    context.set('hornCount', count);
}

// Hoornpuls
function horn(ms, label) {

    hornOn(label);

    addTimer(setTimeout(() => {

        if (!context.get('running')) return;

        hornOff(label);

    }, ms));
}

// ======================================================
// PIEZO CONTROL
// ======================================================

function piezo(on) {

    status(`PIEZO ${on ? 'AAN' : 'UIT'}`);

    node.send([
        null,
        null,
        {
            payload: {
                outputs: {
                    piezo: on ? 1 : 0
                }
            }
        },
        null
    ]);
}

// ======================================================
// START OFF = HARD RESET
// ======================================================

if (run === false) {

    context.set('running', false);

    clearAllTimers();

    context.set('classNumber', 0);
    context.set('hornCount', 0);

    node.send([
        { payload: { outputs: { oranje_vlag: 0 } } },
        { payload: { outputs: { hoorn: 0 } } },
        { payload: { outputs: { piezo: 0 } } },
        { payload: 'START OFF – HARD RESET' }
    ]);

    return null;
}

// ======================================================
// DUBBEL START BLOKKEREN
// ======================================================

if (run !== true || context.get('running')) {
    return null;
}

// ======================================================
// SYSTEEM ACTIEF
// ======================================================

context.set('running', true);

status('START ON');

// ======================================================
// CONFIGURATIE
// ======================================================

// DEBUG SNELHEDEN
const ORANGE_TIME = 0; //20 * 1000;

const T5 = 5 * 60 * 1000;
const T4 = 4 * 60 * 1000;
const T1 = 1 * 60 * 1000;

const PIEZO_BEFORE_START = 10 * 1000;
const PIEZO_BEFORE_FLAG = 3 * 1000;

const HORN_SHORT = 500;
const HORN_LONG = 2000;

// ======================================================
// ORANJE VLAG FASE
// ======================================================

node.send([
    { payload: { outputs: { oranje_vlag: 1 } } },
    null,
    null,
    null
]);

status('ORANJE VLAG OP');

addTimer(setTimeout(() => {

    if (!context.get('running')) return;

    node.send([
        { payload: { outputs: { oranje_vlag: 0 } } },
        null,
        null,
        null
    ]);

    horn(HORN_SHORT, '5 Min signaal');

    scheduleClass(1);

}, ORANGE_TIME));

// ======================================================
// KLASSE SCHEDULER
// ======================================================

function scheduleClass(classNumber) {

    if (!context.get('running')) return;

    context.set('classNumber', classNumber);

    status(`KLASSE ${classNumber} CYCLUS GESTART`);

    // ------------------------------------------
    // 4 MIN
    // ------------------------------------------

    addTimer(setTimeout(() => {

        if (!context.get('running')) return;

        horn(HORN_SHORT, `KLASSE ${classNumber} - (4 MIN)`);

    }, T5 - T4));

    // ------------------------------------------
    // 1 MIN
    // ------------------------------------------

    addTimer(setTimeout(() => {

        if (!context.get('running')) return;

        horn(HORN_SHORT, `KLASSE ${classNumber} - (1 MIN)`);

    }, T5 - T1));

    // ------------------------------------------
    // PIEZO START
    // ------------------------------------------

    addTimer(setTimeout(() => {

        if (!context.get('running')) return;

        piezo(true);

    }, T5 - PIEZO_BEFORE_START));


    // ------------------------------------------
    // START MOMENT
    // ------------------------------------------

    addTimer(setTimeout(() => {

        if (!context.get('running')) return;

        piezo(false);

        horn(HORN_LONG, `KLASSE ${classNumber} START`);

        // Volgende klasse
        scheduleClass(classNumber + 1);

    }, T5));



    addTimer(setTimeout(() => {

        if (!context.get('running')) return;

        piezo(true);

    }, T1 - PIEZO_BEFORE_FLAG));


    addTimer(setTimeout(() => {

        if (!context.get('running')) return;

        piezo(false);

    }, T1-505));

    addTimer(setTimeout(() => {

        if (!context.get('running')) return;

        piezo(true);

    }, T4 - PIEZO_BEFORE_FLAG));

    addTimer(setTimeout(() => {

        if (!context.get('running')) return;

        piezo(false);

    }, T4-505));

}

return null;

// ================= CONFIG =================
const ON_TIME  = 250;  // ms
const OFF_TIME = 750;  // ms

// ================= STATE ==================
let timer = context.get('timer') || null;
let active = context.get('active') || false;

// ================= HELPERS =================
function send(val) {
    node.send({
        payload: {
            outputs: {
                piezo: val
            }
        }
    });
}

function stopBlinking() {
    active = false;
    context.set('active', false);

    if (timer !== null) {
        clearTimeout(timer);
        timer = null;
        context.set('timer', null);
    }

    // Forceer UIT
    send(false);
}

// ================= DEPLOY / CLOSE =================
node.on('close', function () {
    stopBlinking();
});

// ================= LOGIC =================
const cmd = msg && msg.payload && msg.payload.outputs
    ? msg.payload.outputs.piezo
    : undefined;

// START knipperen
if (cmd === 1 && !active) {
    active = true;
    context.set('active', true);

    function loop() {
        if (!context.get('active')) return;

        // AAN
        send(true);

        timer = setTimeout(() => {
            if (!context.get('active')) return;

            // UIT
            send(false);

            timer = setTimeout(() => {
                loop();
            }, OFF_TIME);

            context.set('timer', timer);
        }, ON_TIME);

        context.set('timer', timer);
    }

    loop();
    return null;
}

// STOP knipperen
if (cmd === 0) {
    stopBlinking();
    return null;
}

// Andere berichten negeren
return null;

var state = context.get('state') || false;
state = !state;
context.set('state', state);
msg.payload = state ? true : false;
return msg;

if(msg.payload==true)
{
    msg.payload=1;
}
else
{
    msg=null;    
}
return msg;
